int ListDelete_L(LinkList &L, int i)
{
    LinkList p;
    LinkList q;
    int j;

    p = L;
    j = 0;

    while (p->next && j < i - 1)
    {
        p = p->next;
        ++j;
    }

    if (!(p->next) || j > i - 1)
    {
        return ERROR;
    }

    q = p->next;
    p->next = q->next;
    delete q;

    return OK;
}
```

